class _DeltaMember:
    def __init__(self, index, group_index, member_index, path, member_dir,
                 src, start_offset, start_lineno, old_keys):
        self.index = index
        self.group_index = group_index
        self.member_index = member_index
        self.path = path
        self.member_dir = member_dir
        self.src = src
        self.start_offset = start_offset
        self.start_lineno = start_lineno
        self.old_keys = old_keys

        # Filled by prepare.
        self.dirty = False
        self.offset = start_offset   # drain-end offset on source inode
        self.lineno = start_lineno   # drain-end source line number
        self.base_entry = 0          # durable suffix entries at resume
        self.suffix_good = 0         # good rows in the whole suffix
        self.suffix_bad = 0          # bad rows in the whole suffix
        self.this_good = 0           # rows THIS invocation scans
        self.this_bad = 0
        self.changed = set()         # suffix entries whose bytes change
        self.dropped = set()         # suffix entries dropped (bad refs)
        self.will_stage = False
        self.staged_size = 0
        self.salvaged = 0
        self.conv_skipped = 0

    @property
    def fresh_dropped(self):
        return {n for n in self.dropped if n >= self.base_entry}

    @property
    def lines_added(self):
        return self.this_good + self.this_bad + self.salvaged \
            + self.conv_skipped

    @property
    def records_dropped(self):
        return len(self.fresh_dropped)

    @property
    def records_rewritten(self):
        # Surviving appended rows this invocation scanned whose bytes
        # change (a dropped record never reaches the output).
        return len([
            n for n in self.changed
            if n >= self.base_entry and n not in self.dropped
        ])


